('e3832467-fe79-4802-9f32-c34b86326792','MA','a00a00a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Private Transfers SARL','Atlas Private Transfers','transfer',3,'verified',ARRAY['en','fr','ar'],'Private door-to-door transfers with professional drivers and modern sedan cars. Flight tracking, meet-and-greet at the airport, and 24/7 availability.',7.3,98.6,414,4.3,'active'),
('5d506fb0-f00c-4e20-9345-39df22eef861','MA','a00a00a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Chauffeur Morocco SARL','Royal Chauffeur Morocco','transfer',4,'verified',ARRAY['en','fr','es'],'Luxury chauffeur service with Mercedes E-Class and V-Class vehicles. Leather interiors, bottled water, phone chargers, and English-speaking drivers in suits.',2.4,95.6,423,4.8,'active'),
('10b412f4-3486-4ff0-aa02-c3ce94c2e1f5','MA','a00a00a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','ONCF — Office National des Chemins de Fer SARL','ONCF — Office National des Chemins de Fer','transfer',2,'verified',ARRAY['en','fr','ar'],'Morocco''s national railway operator. High-speed Al Boraq trains connect Tangier to Casablanca via Rabat in under 3 hours. Conventional trains serve Casablanca, Rabat, Fès, Meknès, Marrakech, Tangier, and Oujda. Book at gare.oncf.ma or at any train station.',2,98,1947,4.1,'active'),
('fe14bf3e-3080-4f4b-b3a7-eed8b76222c6','MA','a00a00a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Tetouan Shuttle Express — Station Pickup SARL','Tetouan Shuttle Express — Station Pickup','transfer',1,'verified',ARRAY['en','fr'],'Affordable shared shuttle service between the airport, train stations, and city hotels. Fixed schedules, comfortable minibuses, and friendly drivers. We also offer ONCF station pickup and drop-off services.',1.5,94,68,4.3,'active'),
('df331447-a85d-4e90-b090-dff6afa510d5','MA','a00a00a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Private Transfers — Station Pickup SARL','Atlas Private Transfers — Station Pickup','transfer',3,'verified',ARRAY['en','fr','ar'],'Private door-to-door transfers with professional drivers and modern sedan cars. Flight tracking, meet-and-greet at the airport, and 24/7 availability. We also offer ONCF station pickup and drop-off services.',1.5,94,20,3.9,'active')
